async function snapshots() {
  const result = new Map();
  for (const name of stores) { const p=path.join(root,'data',name); try { result.set(p,{exists:true,data:await fs.readFile(p)}); } catch(e) { if(e.code==='ENOENT') result.set(p,{exists:false}); else throw e; } }
  return result;
}
async function restore(saved) { for (const [p,s] of saved) { if(s.exists) await fs.writeFile(p,s.data); else await fs.rm(p,{force:true}); } }
