async function tabIsolationQA({evaljs}, role) {
  const regular=await evaljs(`(()=>({parent:!!document.querySelector('[data-payment-id="qa-unauthorised"]'),child:!!document.querySelector('[data-payment-id="qa-claimed-child"]'),count:document.querySelector('#tab-all')?.textContent.trim()}))()`);
  assert.equal(regular.parent,false,`${role} Regular excludes unauthorised parent`);
  assert.equal(regular.child,true,`${role} Regular includes claimed child allocation`);
  assert.match(regular.count,/4$/,`${role} Regular count excludes parent and includes child`);
  await evaljs(`document.querySelector('#tab-unauthorised').click();true`);await sleep(40);
  const unauthorised=await evaljs(`(()=>({parent:!!document.querySelector('[data-payment-id="qa-unauthorised"]'),child:!!document.querySelector('[data-payment-id="qa-claimed-child"]'),count:document.querySelector('#tab-unauthorised')?.textContent.trim()}))()`);
  assert.equal(unauthorised.parent,true,`${role} Unauthorised includes parent with remaining balance`);
  assert.equal(unauthorised.child,false,`${role} Unauthorised excludes claimed child allocation`);
  assert.match(unauthorised.count,/1$/,`${role} Unauthorised count includes active parent only`);
  console.log(`PASS ${role} tab isolation regular=${regular.count} unauthorised=${unauthorised.count}`);
}
